  /* ★ 던전 — 맵 안쪽(여백 바깥 2열·위 4줄·아래 4줄 안)의 «안 칠한 칸»은 잘린 축대로 굽는다: 세로로 이어진 안 칠한 칸 묶음 = 축대 띠 · 맨 아랫칸 높이 = 2 − (띠 길이 − 1)/3 (보통 4줄 벽과 같은 기울기 · 앞 2층에 가려 잘린 벽)
   *   도구에서 칠해 두면 저장할 때마다 덮여서 안 칠한 칸 자체를 표시로 쓴다 (사장님 10-23 「아무것도 칠 안된칸이 잘린축대야」·「총 10칸이야」) */
  const 위잘림 = []; let 평면d = null;
