  const 유리기둥칸 = (x, y) => 규칙이름 === 'INSL07' && (x === 43 || x === 45) && y >= 32 && y <= 35;
  for (let y = 32; y <= 35; y++) for (const x of [43, 45]) if (유리기둥칸(x, y) && !(손높이[y*W + x] >= 0)) 손높이[y*W + x] = 1;
  /* INSL07 컨트롤룸 입구 유리 기둥(28·32열 8~11줄 · 지면층 축대로 칠하심) — 43·45열과 같은 방식: 지면은 바닥(1) · 기둥 화소만 오브젝트층 축대(7줄 3 → 12줄 1) (사장님 10-25 [그림] 「이쪽도 방금 처리한 부분과 같은 방식으로 축대 처리해줘.」) — 칠 파일은 안 건드림 */
  const 입구기둥칸 = (x, y) => 규칙이름 === 'INSL07' && (x === 28 || x === 32) && y >= 8 && y <= 11;
  if (규칙이름 === 'INSL07') for (let y = 8; y <= 11; y++) for (const x of [28, 32]) { const i = y*W + x; 칸[i] &= ~축대; 손높이[i] = 1; if (오칸) { 오칸[i] |= 축대; if (!오손) 오손 = new Array(칸.length).fill(-1); 오손[i] = y === 11 ? 1 : -1; } }   /* 11줄 = 띠 밑 1 (바로 아래 12줄 오브젝트층 3 으로 이으면 평평해졌다) */
