  if (규칙이름 === 'INSL07' && 오칸) for (let y = 28; y <= 29; y++) for (const x of [30, 31]) { const i = y*W + x; 오칸[i] |= 축대; if (!오손) 오손 = new Array(칸.length).fill(-1); 오손[i] = y === 29 ? 1 : -1; }
