  /* ☠ 11-12 4~7줄을 비탈로 바꿨다가 되돌림 — 2층(평지 3)이 통째로 사라졌다 (사장님 「위에 구멍뚫린걸 메우랬더니 왜 통째로 없앴어!」) · 칠(평지 3) 그대로 · 구멍 난 자리 그림만 메운다(아래 ⑤) */
  /* ☠ 11-12 아래 여백 여섯 줄을 높이 0 으로 내렸다가 되돌림 — 여백은 1층이 맞고, 없어야 할 것은 옆면이었다 (사장님 「1층이 맞고 옆면이 없는거라고」) */
  /* INSL07 캡슐 방 북서쪽(36~39열 15~18줄 · 칠 «축대 · 높이 미지정») — 미지정 비탈(3→1)이라 지형 판이 없고 그 자리에 갈색 바깥 면만 서서 아래가 검은 틈으로 비었다 → 평지 1 로(미지정 해제 · 칠 파일 불변) → 14줄 벽(3)과 15줄 사이에 수직 벽 옆면(대표 띠 무늬)이 선다 (사장님 11-12 [그림 캡슐 뒤 갈색 판 아래 검은 틈] 「여기 옆면 벽 넣으라고」) */
  /* ☠ 11-12 위 네 줄을 평지 1 로 바꿨다가 되돌림 — 사장님 칠(축대)을 뒤집은 것이었다 */
