      for (let k = 0; k < 3; k++) { const t = m201.layerA[(1 + k + 테[1])*m201.W + 4 + 테[0]] - 1; if (t < 0) continue; const tl = m201.tile(t); for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) { const v = tl[y*TW + x], q = ((k*TH + y)*TW + x)*4; d5[q] = m201.palette[v*3]; d5[q+1] = m201.palette[v*3+1]; d5[q+2] = m201.palette[v*3+2]; d5[q+3] = 255; } }
