  /* 가족 표 [윗줄 첫 블록, 아랫줄 첫 블록] — 네 가족 모두 밑동(갈색 뿌리)은 아랫줄 셋째 열 (블록 그림으로 잼) · FR02 도 같은 복원 (사장님 10-25 「이 복원규칙은 fr02에도 적용해줘.」) */
  const 가족표 = { FR06: [[13, 18], [23, 28], [38, 33], [43, 48]], FR07: [[13, 18], [23, 28], [38, 33], [43, 48]], FR10: [[13, 18], [23, 28], [38, 33], [43, 48]], FR02: [[47, 52], [57, 62], [72, 67], [77, 82]], FR08: [[47, 52], [57, 62], [72, 67], [77, 82]] }[규칙이름];   /* FR08 = FR02 와 같은 블록 (10-25 「08맵 갈거야」) */
